'use client';

import { Tabs as TabsPrimitive } from '@base-ui/react/tabs';
import { useState } from 'react';

import type { AutoplayStep } from '@/registry/ndeko/hooks/use-autoplay';
import { hold } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { positionLabelsOf } from './_parts/axis';
import { ChartCard } from './_parts/chart-card';
import { DataTable, type DataRow } from './_parts/data-table';
import { walkSteps, whileDemonstrating } from './_parts/demo';
import {
  changeWordsOf,
  dayLabelsOf,
  formatCompact,
  formatCount,
  formatUsd,
  percentChangeOf,
} from './_parts/format';
import { LINE_STROKE, MorphPath } from './_parts/morph-path';
import {
  areaPathOf,
  densifyOf,
  linePathOf,
  plotPointsOf,
  VIEW_WIDTH,
  yOf,
  type Point,
} from './_parts/path';
import { PathLayer, PlotFrame } from './_parts/plot';
import {
  Readout,
  ReadoutDot,
  ReadoutRow,
  ReadoutTitle,
} from './_parts/readout';
import {
  columnCenterOf,
  extentOf,
  niceScaleOf,
  percentOf,
  sumOf,
  withZero,
} from './_parts/scale';
import { useChartDemo } from './_parts/use-chart-demo';
import { usePlotWidth } from './_parts/use-plot-width';
import { readingAloud, useReading } from './_parts/use-reading';

type ValueFormat = (value: number) => string;

const SPARK_HEIGHT = 28;

/** Room above and below the curve, so its 2px stroke and its end dot are never cut. */
const SPARK_INSET = 4;

const SPARK_INSETS = 2 * SPARK_INSET;

const SPARK_DRAWN_HEIGHT = SPARK_HEIGHT - SPARK_INSETS;

function lowered(point: Point): Point {
  return { x: point.x, y: point.y + SPARK_INSET };
}

function endStyleOf(end: Point): React.CSSProperties {
  const share = end.x / VIEW_WIDTH;
  return { left: percentOf(share), top: end.y };
}

export type SparklineProps = {
  values: readonly number[];
  /** What the curve shows, for screen readers: a sparkline has no axis to say it. */
  label: string;
  className?: string;
};

/** A curve with no axis: its shape and where it ends. The end wears a dot ringed in the colour of the surface. */
export function Sparkline({ values, label, className }: SparklineProps) {
  const domain = extentOf(values);
  const points = plotPointsOf(values, domain, SPARK_DRAWN_HEIGHT);
  const curve = points.map((point) => lowered(point));
  const end = curve.at(-1);

  return (
    <span
      role='img'
      aria-label={label}
      className={cn('relative block w-full', className)}
      style={{ height: SPARK_HEIGHT }}
    >
      <svg
        aria-hidden='true'
        viewBox={`0 0 ${VIEW_WIDTH} ${SPARK_HEIGHT}`}
        preserveAspectRatio='none'
        className='absolute inset-0 size-full overflow-visible'
      >
        <path
          d={linePathOf(curve)}
          vectorEffect='non-scaling-stroke'
          className={cn(LINE_STROKE, 'stroke-primary')}
        />
      </svg>
      {end && (
        <span
          aria-hidden='true'
          className='bg-primary ring-card absolute size-2 -translate-1/2 rounded-full ring-2'
          style={endStyleOf(end)}
        />
      )}
    </span>
  );
}

export type AreaChartProps = {
  title: string;
  /** A short mark beside the title, such as "Illustrative" over sample data. */
  note?: string;
  /** One label per position: what the readout names and the axis writes. */
  labels: readonly string[];
  values: readonly number[];
  /** What the values count: "Signups". */
  valueName: string;
  /** What one position is, for screen readers: "day". */
  positionNoun?: string;
  formatValue?: ValueFormat;
  formatTick?: ValueFormat;
  /** What sits above the plot: a figure, a sentence, or the tiles that pick what it draws. */
  headline?: React.ReactNode;
  /** Controls beside the title. */
  actions?: React.ReactNode;
  /** Shows the readout at a position without a pointer, for a demonstration. */
  guideIndex?: number | null;
  className?: string;
};

const PLOT_HEIGHT = 160;

const MAX_LINES = 4;

/** The curve is drawn through this many points, so two series of different lengths can glide into each other. */
const MORPH_POINTS = 60;

const FALLBACK_WIDTH = 360;

export function AreaChart({
  title,
  note,
  labels,
  values,
  valueName,
  positionNoun = 'point',
  formatValue = formatCount,
  formatTick = formatCompact,
  headline,
  actions,
  guideIndex = null,
  className,
}: AreaChartProps) {
  const { plotRef, width } = usePlotWidth(FALLBACK_WIDTH);
  const count = values.length;
  const lastIndex = Math.max(count - 1, 0);
  const extent = extentOf(values);
  const domain = withZero(extent);
  const scale = niceScaleOf(domain, MAX_LINES);
  const points = plotPointsOf(values, scale, PLOT_HEIGHT);
  const dense = densifyOf(points, MORPH_POINTS);
  const baseline = yOf(0, scale, PLOT_HEIGHT);
  const reading = useReading({ count, defaultIndex: lastIndex, guideIndex });
  const shownIndex = reading.shownIndex;
  const shownLabel = labels[shownIndex] ?? '';
  const shownNumber = values[shownIndex] ?? 0;
  const shownValue = formatValue(shownNumber);
  const shownTop = yOf(shownNumber, scale, PLOT_HEIGHT);
  const isReadoutShown = reading.isActive && count > 0;
  const firstLabel = labels[0] ?? '';
  const lastLabel = labels[lastIndex] ?? '';
  const summary = `${valueName}: one value per ${positionNoun}, from ${firstLabel} to ${lastLabel}.`;
  const spokenReading = `${shownLabel}: ${shownValue}`;

  const rows: DataRow[] = labels.map((label, index) => {
    const value = values[index] ?? 0;
    return { id: `${index}-${label}`, label, cells: [formatValue(value)] };
  });

  return (
    <ChartCard
      title={title}
      note={note}
      summary={summary}
      actions={actions}
      className={className}
    >
      {headline}
      <PlotFrame
        label={`${valueName}. Use the arrow keys to read each ${positionNoun}.`}
        scale={scale}
        height={PLOT_HEIGHT}
        formatTick={formatTick}
        axisLabels={positionLabelsOf(labels, width)}
        plotRef={plotRef}
        plotProps={reading.handlers}
      >
        <PathLayer height={PLOT_HEIGHT}>
          <MorphPath
            d={areaPathOf(dense, baseline)}
            className='fill-primary/10'
          />
          <MorphPath
            d={linePathOf(dense)}
            className={cn(LINE_STROKE, 'stroke-primary')}
          />
        </PathLayer>
        <Readout
          ratio={columnCenterOf(shownIndex, Math.max(count, 1))}
          top={shownTop}
          isVisible={isReadoutShown}
          isGliding={reading.isGliding}
          marks={<ReadoutDot top={shownTop} color='var(--primary)' />}
        >
          <ReadoutTitle>{shownLabel}</ReadoutTitle>
          <ReadoutRow
            value={shownValue}
            name={valueName}
            color='var(--primary)'
          />
        </Readout>
      </PlotFrame>
      <LiveRegion
        message={readingAloud(reading.isReadingByKeys, spokenReading)}
      />
      <DataTable
        caption={`${valueName} per ${positionNoun}`}
        columns={[positionNoun, valueName]}
        rows={rows}
      />
    </ChartCard>
  );
}

type MetricId = 'signups' | 'trials' | 'conversions' | 'revenue';

type Metric = {
  id: MetricId;
  label: string;
  /** Fourteen days: last week, then this week. */
  values: number[];
  format: ValueFormat;
  formatTick: ValueFormat;
};

const WEEK = 7;

const METRICS: Metric[] = [
  {
    id: 'signups',
    label: 'Signups',
    values: [48, 52, 55, 49, 51, 38, 35, 56, 61, 63, 58, 64, 44, 41],
    format: formatCount,
    formatTick: formatCompact,
  },
  {
    id: 'trials',
    label: 'Trials started',
    values: [19, 22, 21, 24, 20, 14, 12, 22, 25, 24, 27, 23, 15, 13],
    format: formatCount,
    formatTick: formatCompact,
  },
  {
    id: 'conversions',
    label: 'New customers',
    values: [6, 7, 5, 8, 6, 4, 3, 5, 6, 6, 7, 5, 3, 3],
    format: formatCount,
    formatTick: formatCompact,
  },
  {
    id: 'revenue',
    label: 'Revenue',
    values: [
      1180, 1240, 1090, 1320, 1210, 860, 790, 1260, 1310, 1380, 1290, 1420, 940,
      880,
    ],
    format: formatUsd,
    formatTick: formatUsd,
  },
];

const DAYS = dayLabelsOf('2026-05-04', WEEK * 2);

function metricOf(id: MetricId) {
  const metric = METRICS.find((candidate) => candidate.id === id);
  return metric ?? METRICS[0];
}

function weekTotalsOf(metric: Metric) {
  const lastWeek = metric.values.slice(0, WEEK);
  const thisWeek = metric.values.slice(WEEK);
  return { current: sumOf(thisWeek), previous: sumOf(lastWeek) };
}

function changeOf(metric: Metric) {
  const totals = weekTotalsOf(metric);
  const percent = percentChangeOf(totals.current, totals.previous);
  return changeWordsOf(percent, 'last week');
}

type StatTilesProps = {
  metrics: readonly Metric[];
  value: MetricId;
  onValueChange: (id: MetricId) => void;
};

/** Each tile is a tab that picks the curve the plot draws, and shows that same curve in small. */
function StatTiles({ metrics, value, onValueChange }: StatTilesProps) {
  function changeValue(nextValue: unknown) {
    const metric = metrics.find((candidate) => candidate.id === nextValue);
    if (metric) {
      onValueChange(metric.id);
    }
  }

  return (
    <TabsPrimitive.Root value={value} onValueChange={changeValue}>
      <TabsPrimitive.List
        aria-label='Figure drawn in the chart'
        className='relative -mx-2 grid grid-cols-2 gap-x-1 gap-y-2 @md:grid-cols-4'
      >
        {metrics.map((metric) => {
          const totals = weekTotalsOf(metric);
          const change = changeOf(metric);

          return (
            <TabsPrimitive.Tab
              key={metric.id}
              value={metric.id}
              className='group/tile hover:bg-foreground/[0.03] focus-visible:ring-ring/25 flex min-w-0 cursor-pointer flex-col items-start gap-1 rounded-lg px-2 pt-2 pb-3 text-start transition-colors duration-150 outline-none focus-visible:ring-[3px]'
            >
              <span className='text-muted-foreground group-data-active/tile:text-foreground text-xs font-medium transition-colors duration-150'>
                {metric.label}
              </span>
              <span className='text-lg leading-7 font-semibold tabular-nums'>
                {metric.format(totals.current)}
              </span>
              <Sparkline
                values={metric.values}
                label={`${metric.label} over the last 14 days`}
              />
              <span className='text-muted-foreground text-xs text-pretty'>
                {change}
              </span>
            </TabsPrimitive.Tab>
          );
        })}
        <TabsPrimitive.Indicator className='bg-primary pointer-events-none absolute top-0 left-0 h-0.5 w-[calc(var(--active-tab-width)-1rem)] translate-x-[calc(var(--active-tab-left)+0.5rem)] translate-y-[calc(var(--active-tab-top)+var(--active-tab-height)-2px)] rounded-full transition-[translate,width] duration-300 ease-(--ease-out-strong)' />
      </TabsPrimitive.List>
    </TabsPrimitive.Root>
  );
}

const WALK = [8, 9, 10, 11, 12];

export default function Chart03() {
  const [metricId, setMetricId] = useState<MetricId>('signups');
  const [guide, setGuide] = useState<number | null>(null);
  const metric = metricOf(metricId);

  function pickMetric(next: MetricId) {
    setGuide(null);
    setMetricId(next);
  }

  function resetDemo() {
    setMetricId('signups');
    setGuide(null);
  }

  const steps: AutoplayStep[] = [
    ...walkSteps(WALK, setGuide, { startAfter: 1100, stepMs: 320 }),
    { after: 900, run: () => pickMetric('trials') },
    { after: 1700, run: () => pickMetric('conversions') },
    ...walkSteps(WALK, setGuide, { startAfter: 1100, stepMs: 320 }),
    { after: 900, run: () => pickMetric('revenue') },
    { after: 1900, run: () => pickMetric('signups') },
    { after: 1200, run: hold },
  ];
  const { ref, isAutoplaying, stopOnKeyboardFocus } = useChartDemo(steps, {
    loopAfter: 1800,
    onReset: resetDemo,
  });

  return (
    <div
      ref={ref}
      onFocus={stopOnKeyboardFocus}
      className='flex min-h-[26rem] w-full max-w-[34rem]'
    >
      <AreaChart
        title='This week against last week'
        note='Illustrative'
        labels={DAYS}
        values={metric.values}
        valueName={metric.label}
        positionNoun='day'
        formatValue={metric.format}
        formatTick={metric.formatTick}
        headline={
          <StatTiles
            metrics={METRICS}
            value={metricId}
            onValueChange={pickMetric}
          />
        }
        guideIndex={whileDemonstrating(isAutoplaying, guide)}
        className='w-full'
      />
    </div>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

import { yOf } from './path';
import { columnCenterOf, percentOf, type Scale } from './scale';

/** The least room one label of the category axis needs, text and breathing space. */
export const LABEL_ROOM_PX = 56;

type ValueAxisProps = {
  scale: Scale;
  height: number;
  format: (value: number) => string;
  className?: string;
};

/** The figures of the value axis, one per gridline, in a column beside the plot. */
export function ValueAxis({
  scale,
  height,
  format,
  className,
}: ValueAxisProps) {
  return (
    <div
      aria-hidden='true'
      className={cn('relative w-9 shrink-0', className)}
      style={{ height }}
    >
      {scale.ticks.map((tick) => (
        <span
          key={tick}
          className='text-muted-foreground absolute right-0 -translate-y-1/2 text-[11px] tabular-nums'
          style={{ top: yOf(tick, scale, height) }}
        >
          {format(tick)}
        </span>
      ))}
    </div>
  );
}

/** Zero is drawn stronger when values go below it, since bars start there. */
export function gridToneOf(tick: number, scale: Scale) {
  const isZero = tick === 0;
  const crossesZero = scale.min < 0;
  if (isZero && crossesZero) {
    return 'border-foreground/25';
  }
  return 'border-border';
}

type GridLinesProps = {
  scale: Scale;
  height: number;
};

export function GridLines({ scale, height }: GridLinesProps) {
  return (
    <div aria-hidden='true' className='pointer-events-none absolute inset-0'>
      {scale.ticks.map((tick) => (
        <span
          key={tick}
          className={cn(
            'hairline-t absolute inset-x-0',
            gridToneOf(tick, scale)
          )}
          style={{ top: yOf(tick, scale, height) }}
        />
      ))}
    </div>
  );
}

export type AxisLabel = {
  id: string;
  text: string;
  /** From 0 at the left edge of the plot to 1 at its right edge. */
  ratio: number;
  isStrong?: boolean;
};

/** Every how many positions a label is written, so the labels that are written never touch. */
export function labelStepOf(count: number, plotWidth: number) {
  const fitting = Math.floor(plotWidth / LABEL_ROOM_PX);
  const labelCount = Math.max(fitting, 1);
  const step = Math.ceil(count / labelCount);
  return Math.max(step, 1);
}

/** The labels kept when one in `step` is written, counted back from the last so the latest is always named. */
export function spacedLabelsOf(labels: readonly AxisLabel[], step: number) {
  const lastIndex = labels.length - 1;
  return labels.filter((_, index) => {
    const fromLast = lastIndex - index;
    return fromLast % step === 0;
  });
}

/**
 * One label per position, under the middle of its column, written as often as the room allows. The
 * one at `strongIndex`, such as today, is set stronger.
 */
export function positionLabelsOf(
  labels: readonly string[],
  plotWidth: number,
  strongIndex?: number
) {
  const all: AxisLabel[] = labels.map((text, index) => ({
    id: `${index}-${text}`,
    text,
    ratio: columnCenterOf(index, labels.length),
    isStrong: index === strongIndex,
  }));
  const step = labelStepOf(labels.length, plotWidth);
  return spacedLabelsOf(all, step);
}

function strongOf(isStrong: boolean | undefined) {
  if (isStrong) {
    return 'text-foreground font-medium';
  }
  return 'text-muted-foreground';
}

type LabelAlign = 'spread' | 'center';

/**
 * A spread label slides from its left edge to its right edge as it crosses the plot, like the
 * readout, so the first and the last never stick out of the piece. A centred label sits under its
 * mark, for the few wide columns of a bar chart.
 */
function labelStyleOf(
  label: AxisLabel,
  align: LabelAlign
): React.CSSProperties {
  const left = percentOf(label.ratio);
  if (align === 'center') {
    return { left, transform: 'translateX(-50%)' };
  }
  const shift = percentOf(-label.ratio);
  return { left, transform: `translateX(${shift})` };
}

type CategoryAxisProps = {
  labels: readonly AxisLabel[];
  align?: LabelAlign;
  className?: string;
};

export function CategoryAxis({
  labels,
  align = 'spread',
  className,
}: CategoryAxisProps) {
  return (
    <div aria-hidden='true' className={cn('relative h-4', className)}>
      {labels.map((label) => (
        <span
          key={label.id}
          className={cn(
            'absolute top-0 text-[11px] whitespace-nowrap tabular-nums',
            strongOf(label.isStrong)
          )}
          style={labelStyleOf(label, align)}
        >
          {label.text}
        </span>
      ))}
    </div>
  );
}

import { useId } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';

type ChartCardProps = {
  title: string;
  /** A short mark beside the title, such as "Illustrative" over sample data. */
  note?: string;
  /** One line that says what the chart shows, read by screen readers with the title. */
  summary: string;
  /** Controls that change what the chart draws: a period, a view. */
  actions?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
};

/**
 * The surface every chart sits on. It is a query container, so a chart lays itself out by the
 * room it has, and it is positioned, so the hidden table of a chart never widens the page.
 */
export function ChartCard({
  title,
  note,
  summary,
  actions,
  className,
  children,
}: ChartCardProps) {
  const titleId = useId();
  const summaryId = useId();

  return (
    <section
      aria-labelledby={titleId}
      aria-describedby={summaryId}
      className={cn(
        'bg-card hairline-ring ring-border @container relative flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <header className='flex min-h-7 flex-wrap items-center justify-between gap-x-3 gap-y-2'>
        <div className='flex min-w-0 items-center gap-2'>
          <h3 id={titleId} className='text-sm font-medium text-balance'>
            {title}
          </h3>
          {note && <Badge variant='secondary'>{note}</Badge>}
        </div>
        {actions}
      </header>
      {children}
      <p id={summaryId} className='sr-only'>
        {summary}
      </p>
    </section>
  );
}

export type DataRow = {
  id: string;
  /** The heading of the row: a day, a category, a step. */
  label: string;
  cells: readonly string[];
};

type DataTableProps = {
  caption: string;
  /** The heading of the label column first, then one per cell. */
  columns: readonly string[];
  rows: readonly DataRow[];
};

/**
 * The numbers a chart draws, as a table for screen readers. It is taken out of the flow, so the
 * piece it sits in has to be positioned: a hidden box inside an area that scrolls sideways widens
 * the page otherwise.
 */
export function DataTable({ caption, columns, rows }: DataTableProps) {
  return (
    <table className='sr-only'>
      <caption>{caption}</caption>
      <thead>
        <tr>
          {columns.map((column) => (
            <th key={column} scope='col'>
              {column}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.id}>
            <th scope='row'>{row.label}</th>
            {row.cells.map((cell, index) => (
              <td key={index}>{cell}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

import type { AutoplayStep } from '@/registry/ndeko/hooks/use-autoplay';
import { keyDelayOf } from '@/registry/ndeko/lib/demonstration';

type WalkOptions = {
  /** Milliseconds before the first position. */
  startAfter?: number;
  /** Milliseconds between two positions. */
  stepMs?: number;
};

/** One step per position, so a reading crosses a plot the way a pointer does. */
export function walkSteps<Position>(
  positions: readonly Position[],
  moveTo: (position: Position) => void,
  { startAfter = 700, stepMs = 240 }: WalkOptions = {}
): AutoplayStep[] {
  return positions.map((position, index) => {
    const after = keyDelayOf(index, startAfter, stepMs);
    return { after, run: () => moveTo(position) };
  });
}

/** What a demonstration points at lets go the moment a person takes over. */
export function whileDemonstrating<Value>(
  isDemonstrating: boolean,
  value: Value | null
) {
  if (isDemonstrating) {
    return value;
  }
  return null;
}

const LOCALE = 'en-US';

export const COUNT_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
};

export const SIGNED_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
  signDisplay: 'exceptZero',
};

export const USD_COMPACT_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COMPACT_FORMAT: Intl.NumberFormatOptions = {
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COUNT = new Intl.NumberFormat(LOCALE, COUNT_FORMAT);

const SIGNED = new Intl.NumberFormat(LOCALE, SIGNED_FORMAT);

const COMPACT = new Intl.NumberFormat(LOCALE, COMPACT_FORMAT);

const USD_COMPACT = new Intl.NumberFormat(LOCALE, USD_COMPACT_FORMAT);

const DAY = new Intl.DateTimeFormat(LOCALE, {
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
});

const MS_PER_DAY = 86_400_000;

export function formatCount(value: number) {
  return COUNT.format(value);
}

export function formatSigned(value: number) {
  return SIGNED.format(value);
}

export function formatCompact(value: number) {
  return COMPACT.format(value);
}

export function formatUsd(value: number) {
  return USD_COMPACT.format(value);
}

export function formatShare(share: number) {
  const percent = Math.round(share * 100);
  return `${percent}%`;
}

/** A start at zero has no percentage to grow from: it reads as no change. */
export function percentChangeOf(current: number, previous: number) {
  if (previous === 0) {
    return 0;
  }
  const difference = current - previous;
  const ratio = difference / Math.abs(previous);
  return Math.round(ratio * 100);
}

export function changeWordsOf(percent: number, reference: string) {
  if (percent === 0) {
    return `level with ${reference}`;
  }
  const size = Math.abs(percent);
  if (percent > 0) {
    return `up ${size}% on ${reference}`;
  }
  return `down ${size}% on ${reference}`;
}

export function nounOf(count: number, singular: string, plural: string) {
  if (count === 1) {
    return singular;
  }
  return plural;
}

/**
 * One label per day, or per `everyDays` days for a weekly series. Days are counted in UTC so the
 * server and the browser write the same label.
 */
export function dayLabelsOf(firstDay: string, count: number, everyDays = 1) {
  const start = Date.parse(`${firstDay}T00:00:00Z`);
  const stride = everyDays * MS_PER_DAY;
  return Array.from({ length: count }, (_, index) => {
    const elapsed = index * stride;
    return DAY.format(start + elapsed);
  });
}

'use client';

import { motion, type Transition } from 'motion/react';
import { useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG, INSTANT } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

const MORPH: Transition = { duration: 0.3, ease: EASE_OUT_STRONG };

/** What is there on mount does not fade in: only a shape that replaced another one does. */
const SWAP_FADE =
  'transition-opacity duration-200 ease-(--ease-out-strong) starting:opacity-0';

function transitionOf(isInstant: boolean) {
  if (isInstant) {
    return INSTANT;
  }
  return MORPH;
}

function swapFadeOf(hasChanged: boolean) {
  if (hasChanged) {
    return SWAP_FADE;
  }
  return undefined;
}

/** False until the value changes for the first time. */
function useHasChanged(value: string) {
  const [firstValue] = useState(value);
  const [hasChanged, setHasChanged] = useState(false);
  const isFirstChange = value !== firstValue && !hasChanged;
  if (isFirstChange) {
    setHasChanged(true);
  }
  return hasChanged;
}

type MorphPathProps = {
  d: string;
  /** True while the shape follows a hand: it is redrawn where the hand is, with no glide behind it. */
  isInstant?: boolean;
  className?: string;
  style?: React.CSSProperties;
  /** For a shape that is its own hit target. */
  onPointerEnter?: () => void;
};

/**
 * A shape that glides to its new outline when the data changes, as long as both outlines have the
 * same number of points. Under reduced motion the new shape replaces the old one with a fade.
 */
export function MorphPath({
  d,
  isInstant = false,
  className,
  style,
  onPointerEnter,
}: MorphPathProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const hasChanged = useHasChanged(d);

  if (shouldReduceMotion) {
    return (
      <path
        key={d}
        d={d}
        vectorEffect='non-scaling-stroke'
        className={cn(swapFadeOf(hasChanged), className)}
        style={style}
        onPointerEnter={onPointerEnter}
      />
    );
  }

  return (
    <motion.path
      initial={false}
      animate={{ d }}
      transition={transitionOf(isInstant)}
      vectorEffect='non-scaling-stroke'
      className={className}
      style={style}
      onPointerEnter={onPointerEnter}
    />
  );
}

/** The stroke of a line: 2px whatever the width of the plot, with round joins and ends. */
export const LINE_STROKE =
  'fill-none stroke-2 [stroke-linecap:round] [stroke-linejoin:round]';

import { columnCenterOf, lerp, ratioOf, type Domain } from './scale';

export type Point = {
  x: number;
  y: number;
};

/** Paths are drawn in a box this wide and stretched to the plot, so a change of width never redraws them. */
export const VIEW_WIDTH = 1000;

function commandOf(point: Point, index: number) {
  const x = point.x.toFixed(1);
  const y = point.y.toFixed(1);
  if (index === 0) {
    return `M${x} ${y}`;
  }
  return `L${x} ${y}`;
}

export function linePathOf(points: readonly Point[]) {
  const commands = points.map((point, index) => commandOf(point, index));
  return commands.join(' ');
}

/** The line closed down (or up) to a level, for the wash under a line. */
export function areaPathOf(points: readonly Point[], levelY: number) {
  if (points.length === 0) {
    return '';
  }
  const line = linePathOf(points);
  const lastIndex = points.length - 1;
  const firstX = points[0].x.toFixed(1);
  const lastX = points[lastIndex].x.toFixed(1);
  const level = levelY.toFixed(1);
  return `${line} L${lastX} ${level} L${firstX} ${level} Z`;
}

/** The surface between two lines that share their x positions, for a range around a line. */
export function bandPathOf(upper: readonly Point[], lower: readonly Point[]) {
  if (upper.length === 0) {
    return '';
  }
  const backwards = [...lower].reverse();
  const outline = [...upper, ...backwards];
  const line = linePathOf(outline);
  return `${line} Z`;
}

/** The pixel height of a value in a plot: the top of the domain is 0, its bottom is the plot height. */
export function yOf(value: number, domain: Domain, height: number) {
  const ratio = ratioOf(value, domain);
  const fromBottom = ratio * height;
  return height - fromBottom;
}

/** One point per value, each in the middle of its column. */
export function plotPointsOf(
  values: readonly number[],
  domain: Domain,
  height: number
): Point[] {
  return values.map((value, index) => {
    const share = columnCenterOf(index, values.length);
    const x = share * VIEW_WIDTH;
    const y = yOf(value, domain, height);
    return { x, y };
  });
}

/** How many of the pieces lie before a segment when they are shared out evenly. */
function piecesBefore(
  segment: number,
  segmentCount: number,
  pieceCount: number
) {
  const share = segment / segmentCount;
  return Math.floor(share * pieceCount);
}

/**
 * The same line through exactly `count` points: each segment is cut into equal parts, so two lines
 * of different lengths share one structure and one can glide into the other.
 */
export function densifyOf(points: readonly Point[], count: number): Point[] {
  const segmentCount = points.length - 1;
  const hasSegments = segmentCount >= 1;
  const hasRoom = count > points.length;
  if (!hasSegments || !hasRoom) {
    return [...points];
  }
  const pieceCount = count - 1;
  const dense: Point[] = [points[0]];
  for (let segment = 0; segment < segmentCount; segment += 1) {
    const from = points[segment];
    const to = points[segment + 1];
    const start = piecesBefore(segment, segmentCount, pieceCount);
    const end = piecesBefore(segment + 1, segmentCount, pieceCount);
    const parts = end - start;
    for (let part = 1; part <= parts; part += 1) {
      const amount = part / parts;
      const x = lerp(from.x, to.x, amount);
      const y = lerp(from.y, to.y, amount);
      dense.push({ x, y });
    }
  }
  return dense;
}

