}

type ReadoutDotProps = {
  /** Pixels from the top of the plot. */
  top: number;
  color: string;
};

/** The mark of one series where the crosshair meets it, ringed in the colour of the surface. */
export function ReadoutDot({ top, color }: ReadoutDotProps) {
  const style = {
    backgroundColor: color,
    transform: `translate(-50%, ${top}px)`,
  };

  return (
    <span
      className={cn(
        'ring-card absolute -top-1 left-0 size-2 rounded-full ring-2',
        MARK_GLIDE
      )}
      style={style}
    />
  );
}

export type Domain = {
  min: number;
  max: number;
};

export type Scale = Domain & {
  step: number;
  ticks: number[];
};

const NICE_FACTORS = [1, 2, 5, 10];

const EMPTY_DOMAIN: Domain = { min: 0, max: 0 };

export function clamp(value: number, min: number, max: number) {
  const atLeastMin = Math.max(value, min);
  return Math.min(atLeastMin, max);
}

export function lerp(from: number, to: number, amount: number) {
  const span = to - from;
  return from + span * amount;
}

export function sumOf(values: readonly number[]) {
  let total = 0;
  for (const value of values) {
    total += value;
  }
  return total;
}

export function extentOf(values: readonly number[]): Domain {
  if (values.length === 0) {
    return EMPTY_DOMAIN;
  }
  let min = values[0];
  let max = values[0];
  for (const value of values) {
    min = Math.min(min, value);
    max = Math.max(max, value);
  }
  return { min, max };
}

/** Bars and areas are read from zero, so their domain always holds it. */
export function withZero(domain: Domain): Domain {
  const min = Math.min(domain.min, 0);
  const max = Math.max(domain.max, 0);
  return { min, max };
}

/** Where a value sits in a domain, from 0 at its lowest to 1 at its highest. */
export function ratioOf(value: number, domain: Domain) {
  const span = domain.max - domain.min;
  if (span === 0) {
    return 0;
  }
  const offset = value - domain.min;
  return offset / span;
}

/** A flat series still needs room above and below it to be drawn. */
function spanOf(domain: Domain) {
  const span = domain.max - domain.min;
  if (span > 0) {
    return span;
  }
  const size = Math.abs(domain.max);
  return Math.max(size, 1);
}

function niceStepOf(roughStep: number) {
  const logarithm = Math.log10(roughStep);
  const exponent = Math.floor(logarithm);
  const magnitude = 10 ** exponent;
  const factor = NICE_FACTORS.find((candidate) => {
    const candidateStep = candidate * magnitude;
    return candidateStep >= roughStep;
  });
  const safeFactor = factor ?? 10;
  return safeFactor * magnitude;
}

function decimalsOf(step: number) {
  const logarithm = Math.log10(step);
  const exponent = Math.floor(logarithm);
  return Math.max(0, -exponent);
}

/** Adding zero turns a negative zero into zero, which a number format would write as -0. */
function roundedTo(value: number, decimals: number) {
  const factor = 10 ** decimals;
  const scaled = Math.round(value * factor);
  const rounded = scaled / factor;
  return rounded + 0;
}

/** A scale with round ticks that holds the whole domain, in at most `maxLines` steps. */
export function niceScaleOf(domain: Domain, maxLines: number): Scale {
  const span = spanOf(domain);
  const roughStep = span / maxLines;
  const step = niceStepOf(roughStep);
  const decimals = decimalsOf(step);
  const stepsBelow = Math.floor(domain.min / step);
  const lowest = stepsBelow * step;
  const highestWanted = Math.max(domain.max, lowest + step);
  const stepsAbove = Math.ceil(highestWanted / step);
  const lineCount = stepsAbove - stepsBelow;
  const tickCount = lineCount + 1;
  const ticks = Array.from({ length: tickCount }, (_, index) => {
    const tick = lowest + index * step;
    return roundedTo(tick, decimals);
  });
  const lastIndex = ticks.length - 1;
  return { min: ticks[0], max: ticks[lastIndex], step, ticks };
}

/** Columns share the plot equally and a mark sits in the middle of its column. */
export function columnCenterOf(index: number, count: number) {
  const center = index + 0.5;
  return center / count;
}

export function columnIndexAt(ratio: number, count: number) {
  const rawIndex = Math.floor(ratio * count);
  const lastIndex = Math.max(count - 1, 0);
  return clamp(rawIndex, 0, lastIndex);
}

export function percentOf(share: number) {
  const percent = share * 100;
  return `${percent}%`;
}

/** The whole numbers that lead from one position to another: the start is left out, the end is kept. */
export function positionsTo(from: number, to: number) {
  const gap = to - from;
  const distance = Math.abs(gap);
  const direction = Math.sign(gap);
  return Array.from({ length: distance }, (_, index) => {
    const travelled = index + 1;
    const offset = travelled * direction;
    return from + offset;
  });
}

'use client';

import {
  useAutoplay,
  type AutoplayOptions,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { useKeptHeight } from '@/registry/ndeko/hooks/use-kept-height';

/**
 * What every chart demo shares: the demonstration, the box that keeps its tallest height so a round
 * never moves the page, and a stop when the keyboard brings focus in. A person who tabs to a plot
 * reads it with the arrow keys from there, and has pressed no key inside the piece yet.
 */
export function useChartDemo(
  steps: readonly AutoplayStep[],
  options?: AutoplayOptions
) {
  const demo = useAutoplay(steps, options);
  const { ref, takeOver } = demo;

  useKeptHeight(ref);

  function stopOnKeyboardFocus(event: React.FocusEvent<HTMLElement>) {
    const isKeyboardFocus = event.target.matches(':focus-visible');
    if (isKeyboardFocus) {
      takeOver();
    }
  }

  return { ...demo, stopOnKeyboardFocus };
}

'use client';

import { useLayoutEffect, useState } from 'react';

/**
 * The width of a plot as it resizes, for what depends on the room it has: how many labels fit, how
 * many marks, which way the bars run. Shapes do not need it: they are drawn in shares of the plot.
 */
export function usePlotWidth(fallback: number) {
  const [target, setTarget] = useState<HTMLElement | null>(null);
  const [width, setWidth] = useState(fallback);

  useLayoutEffect(() => {
    if (!target) {
      return;
    }
    const observer = new ResizeObserver(([entry]) => {
      const box = entry.contentBoxSize[0];
      setWidth(box.inlineSize);
    });
    observer.observe(target);
    return () => observer.disconnect();
  }, [target]);

  return { plotRef: setTarget, width };
}

'use client';

import { useState } from 'react';

import { clamp, columnIndexAt } from './scale';

type ReadingOptions = {
  /** How many positions the plot has from left to right. */
  count: number;
  /** Where the reading opens the first time the plot takes keyboard focus. */
  defaultIndex: number;
  /** A position shown from outside while nobody reads the plot, for a demonstration. */
  guideIndex?: number | null;
  /** Enter, Space or a click on a position. */
  onSelect?: (index: number) => void;
};

function columnIndexFrom(
  event: React.PointerEvent<HTMLElement> | React.MouseEvent<HTMLElement>,
  count: number
) {
  const box = event.currentTarget.getBoundingClientRect();
  const offset = event.clientX - box.left;
  const ratio = offset / box.width;
  return columnIndexAt(ratio, count);
}

export function steppedIndexOf(key: string, current: number, count: number) {
  const lastIndex = Math.max(count - 1, 0);
  if (key === 'ArrowRight') {
    const next = current + 1;
    return Math.min(next, lastIndex);
  }
  if (key === 'ArrowLeft') {
    const previous = current - 1;
    return Math.max(previous, 0);
  }
  if (key === 'Home') {
    return 0;
  }
  if (key === 'End') {
    return lastIndex;
  }
  return null;
}

export function activeIndexOf(isActive: boolean, shownIndex: number) {
  if (isActive) {
    return shownIndex;
  }
  return null;
}

/** A reading is said aloud only while the arrow keys move it: a pointer and a demonstration stay silent. */
export function readingAloud(isReadingByKeys: boolean, reading: string) {
  if (isReadingByKeys) {
    return reading;
  }
  return '';
}

function isSelectKey(key: string) {
  const isEnter = key === 'Enter';
  const isSpace = key === ' ';
  return isEnter || isSpace;
}

/**
 * One reading position for a plot that is one tab stop. The pointer wins while it is over the plot,
 * then the arrow keys, then the position a demonstration points at. A reading that opens appears in
 * place; one that moves glides, which `isGliding` tells the readout.
 *
 * A plot read by columns spreads `handlers`. A plot whose marks are their own hit targets spreads
 * `markHandlers` and calls `pointTo` from each mark.
 */
export function useReading({
  count,
  defaultIndex,
  guideIndex = null,
  onSelect,
}: ReadingOptions) {
  const [pointerIndex, setPointerIndex] = useState<number | null>(null);
  const [keyIndex, setKeyIndex] = useState<number | null>(null);
  const [lastIndex, setLastIndex] = useState(defaultIndex);
  const [isGliding, setIsGliding] = useState(false);
  const [seenGuide, setSeenGuide] = useState(guideIndex);
  const hasNewGuide = seenGuide !== guideIndex;

  if (hasNewGuide) {
    const wasGuided = seenGuide !== null;
    const isGuided = guideIndex !== null;
    setSeenGuide(guideIndex);
    setIsGliding(wasGuided && isGuided);
    if (guideIndex !== null) {
      setLastIndex(guideIndex);
    }
  }

  const activeIndex = pointerIndex ?? keyIndex ?? guideIndex;
  const isActive = activeIndex !== null;
  const isPointing = pointerIndex !== null;
  const isReadingByKeys = keyIndex !== null;
  const wantedIndex = activeIndex ?? lastIndex;
  const highestIndex = Math.max(count - 1, 0);
  const shownIndex = clamp(wantedIndex, 0, highestIndex);

  function pointAt(event: React.PointerEvent<HTMLElement>) {
    const index = columnIndexFrom(event, count);
    setIsGliding(isPointing);
    setPointerIndex(index);
    setLastIndex(index);
  }

  /** Null when the pointer is over the plot and on no mark. */
  function pointTo(index: number | null) {
    if (index === null) {
      setPointerIndex(null);
      return;
    }
    setIsGliding(isPointing);
    setPointerIndex(index);
    setLastIndex(index);
  }

  function leave(event: React.PointerEvent<HTMLElement>) {
    if (event.pointerType === 'mouse') {
      setPointerIndex(null);
    }
  }

  function focus(event: React.FocusEvent<HTMLElement>) {
    const isKeyboardFocus = event.currentTarget.matches(':focus-visible');
    if (isKeyboardFocus) {
      setIsGliding(false);
      setKeyIndex(shownIndex);
    }
  }

  function blur() {
    setKeyIndex(null);
    setPointerIndex(null);
  }

  function pressKey(event: React.KeyboardEvent<HTMLElement>) {
    if (event.key === 'Escape') {
      setKeyIndex(null);
      return;
    }
    if (isSelectKey(event.key)) {
      if (onSelect) {
        event.preventDefault();
        setKeyIndex(shownIndex);
        onSelect(shownIndex);
      }
      return;
    }
    const next = steppedIndexOf(event.key, shownIndex, count);
    if (next === null) {
      return;
    }
    event.preventDefault();
    setIsGliding(isActive);
    setPointerIndex(null);
    setKeyIndex(next);
    setLastIndex(next);
  }

  function click(event: React.MouseEvent<HTMLElement>) {
    if (!onSelect) {
      return;
    }
    const index = columnIndexFrom(event, count);
    onSelect(index);
  }

  const handlers = {
    onPointerMove: pointAt,
    onPointerDown: pointAt,
    onPointerLeave: leave,
    onFocus: focus,
    onBlur: blur,
    onKeyDown: pressKey,
    onClick: click,
  };

  const markHandlers = {
    onPointerLeave: leave,
    onFocus: focus,
    onBlur: blur,
    onKeyDown: pressKey,
  };

  return {
    shownIndex,
    isActive,
    isGliding,
    isPointing,
    isReadingByKeys,
    handlers,
    markHandlers,
    pointTo,
  };
}
